import{j as e}from"./index-Cvn8XixQ.js";import{G as t}from"./GuidePageLayout-DjCFcGug.js";import"./PageBanner-C2RyqhZh.js";import"./Breadcrumbs-C1y9bcgc.js";import"./chevron-right-B7ezrMbL.js";import"./ServicePageLayout-DL5HiLt9.js";import"./button-W0vxHA79.js";function u(){return e.jsx(t,{"code-path":"src\\pages\\guides\\SmsSurvey.tsx:5:5",title:"SMS Surveys in Kenya (2026)",subtitle:"How to run two-way SMS feedback that gets answers",description:"A guide to running SMS surveys in Kenya: two-way flows, branching questions, response rates, real-time analytics, and CAK/ODPC compliance — using MobiWave's bundled SMS, USSD and WhatsApp channels.",breadcrumbLabel:"SMS Survey Kenya",updated:"August 2026",intro:"SMS surveys reach every Kenyan phone, including feature phones with no data — so response rates beat email, especially outside major cities. This guide covers how to design, send and analyze them compliantly.",checklist:["A CAK-registered sender ID (MobiWave handles it)","Consent / opt-in for the audience you survey","Short, single-topic questions","Branching plan for follow-ups","Reminder strategy for non-responders","Plan for ODPC-aligned data handling"],steps:[{step:"1",title:"Register your sender ID",description:"MobiWave registers your CAK-aligned sender ID on Safaricom, Airtel and Telkom at no extra admin fee, so surveys arrive from a trusted name."},{step:"2",title:"Design the survey",description:"Build single-choice, rating, NPS or open-text questions with branching so later questions depend on earlier answers."},{step:"3",title:"Send and collect",description:"Dispatch to a segmented list over two-way SMS. Responses stream back in real time and post to your webhook."},{step:"4",title:"Remind non-responders",description:"Automated nudges re-message people who haven’t replied, lifting completion without manual chasing."},{step:"5",title:"Analyze",description:"Track completion, distributions and drop-off in the dashboard; export CSV or wire into BI tools."},{step:"6",title:"Act and bundle",description:"Trigger follow-ups from results and combine surveys with bulk SMS, USSD and WhatsApp on one account."}],comparison:{headers:["MobiWave","Africa's Talking","Celcom Africa","Twilio"],note:"All support two-way SMS surveys. MobiWave bundles surveys with SMS, USSD and WhatsApp and handles CAK sender-ID registration at no admin fee.",rows:[{name:"Two-way SMS surveys",cells:[{text:"Included",highlight:!0},{text:"Add-on"},{text:"Add-on"},{text:"Add-on"}]},{name:"Branching / skip logic",cells:[{text:"Yes",highlight:!0},{text:"DIY via API"},{text:"DIY"},{text:"DIY"}]},{name:"Sender ID registration",cells:[{text:"Free, handled for you",highlight:!0},{text:"KES 7,000 / network"},{text:"KES 7,000 / network"},{text:"Via aggregator"}]},{name:"Real-time analytics",cells:[{text:"Dashboard + webhook",highlight:!0},{text:"API only"},{text:"API only"},{text:"API only"}]},{name:"Local 24/7 support",cells:[{text:"Phone + WhatsApp",highlight:!0},{text:"Developer-only"},{text:"Business hours"},{text:"No local team"}]}]},faqs:[{question:"How much does an SMS survey cost in Kenya?",answer:"You pay per SMS sent and received at MobiWave’s standard bulk SMS rate (KES 0.20–0.35 by volume), with no extra fee for the survey tooling. No setup fees — contact us for volume pricing."},{question:"What response rates can I expect?",answer:"SMS typically outperforms email, especially among customers without smartphones or reliable data. A recognized sender ID, short questions and one reminder lift completion further."},{question:"Can I ask different questions based on answers?",answer:'Yes. Branching and skip logic route a "No" to a different follow-up than a "Yes", keeping surveys short and relevant.'},{question:"Does it work on feature phones?",answer:"Yes. SMS surveys run on every GSM phone with no app or internet — ideal for rural and low-connectivity audiences."},{question:"Can surveys be in Swahili?",answer:"Yes. Questions, responses and reminders can be in Swahili or English, localized per segment."},{question:"How do you keep surveys compliant?",answer:"We keep an opt-in/opt-out ledger and honor STOP-to-unsubscribe on every flow, supporting ODPC and CAK rules. Survey data is handled under MobiWave’s privacy commitments."},{question:"Can I run NPS over SMS?",answer:"Yes. NPS and rating types are supported, segmented into promoters, passives and detractors for follow-up."},{question:"Where do responses go?",answer:"Responses appear in the real-time dashboard and post to your webhook for piping into CRM or BI tools."},{question:"Can I survey over WhatsApp too?",answer:"Yes. The same logic can run over WhatsApp for customers who prefer it, on the same account."},{question:"How is MobiWave different from Africa’s Talking?",answer:"Both support two-way SMS. MobiWave includes branching surveys, reminder automation and a real-time dashboard, registers your CAK sender ID for free, and bundles SMS with USSD and WhatsApp — with 24/7 local support."}],relatedRoutes:[{label:"SMS Surveys",href:"/services/sms-surveys"},{label:"Bulk SMS",href:"/services/bulk-sms"},{label:"Best Bulk SMS Provider",href:"/guides/best-bulk-sms-kenya"}]})}export{u as SmsSurveyGuide};
